N_5r: { bg: 'toilet', t: 0.4, amb: 'toilet', lines: s => {
  const v = s.v;
  if (v.heardHer && v.stayed) return [
    n('私は、汐音の隣に座った。何も言わずに。'),
    n('長い沈黙のあと、汐音が、ぽつりと言った。', { sp: ['sio_bust:center'] }),
    sio('……ありがとう。そばにいてくれて。'),
    sio('みんなの前では、聞かないでほしいの。気づいても、気づかないふりしてくれたら、それがいちばん、助かる。')
  ];
  if (v.heardHer) return [
    n('汐音は、目を丸くして、それから、少しだけ、笑った。', { sp: ['sio_bust:center'] }),
    sio('……そんなこと、初めて聞かれた。'),
    sio('みんなの前では、聞かないでほしいの。気づいても、気づかないふりしてくれたら、それがいちばん、助かる。'),
    sio('先生には、私から、ちゃんと話す。……でも、そばにいてくれたら、心強いな。')
  ];
  if (v.decided) return [
    sio('……え。待って。', { sp: ['sio_bust:center'] }),
    sio('それは、私が、決めたいかな。'),
    n('汐音は、それ以上は何も言わなかった。でも、扉の隙間が、少しだけ、狭くなった。', { set: { watch: 1 } })
  ];
  return [
    sio('……ありがとう。ちゃんと、調べてみるね。', { sp: ['sio_bust:center'] }),
    n('やさしい声だった。でも、その「ありがとう」は、扉を閉める音に、少し似ていた。', { set: { watch: 1 } })
  ];
}, next: 'N_6' },

